/**
 * GraphQL query and mutation strings for the comments system.
 */
/** Search for a discussion by title — full data (used by drawer) */
export declare const SEARCH_DISCUSSION = "\n  query SearchDiscussion($query: String!) {\n    search(query: $query, type: DISCUSSION, first: 1) {\n      nodes {\n        ... on Discussion {\n          id\n          title\n          body\n          url\n          comments(first: 100) {\n            nodes {\n              id\n              body\n              createdAt\n              author {\n                login\n                avatarUrl\n              }\n              replies(first: 50) {\n                nodes {\n                  id\n                  body\n                  createdAt\n                  author {\n                    login\n                    avatarUrl\n                  }\n                  reactionGroups {\n                    content\n                    users(first: 0) { totalCount }\n                    viewerHasReacted\n                  }\n                }\n              }\n              reactionGroups {\n                content\n                users(first: 0) { totalCount }\n                viewerHasReacted\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n";
/** Search for a discussion — lightweight (pins only: id, body for metadata, author) */
export declare const SEARCH_DISCUSSION_LIGHTWEIGHT = "\n  query SearchDiscussionLightweight($query: String!) {\n    search(query: $query, type: DISCUSSION, first: 1) {\n      nodes {\n        ... on Discussion {\n          id\n          title\n          url\n          comments(first: 100) {\n            nodes {\n              id\n              body\n              author {\n                login\n                avatarUrl\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n";
/** Fetch full detail for a single comment by node ID */
export declare const GET_COMMENT_DETAIL = "\n  query GetCommentDetail($id: ID!) {\n    node(id: $id) {\n      ... on DiscussionComment {\n        id\n        body\n        createdAt\n        discussion {\n          id\n        }\n        author {\n          login\n          avatarUrl\n        }\n        replies(first: 50) {\n          nodes {\n            id\n            body\n            createdAt\n            author {\n              login\n              avatarUrl\n            }\n            reactionGroups {\n              content\n              users(first: 0) { totalCount }\n              viewerHasReacted\n            }\n          }\n        }\n        reactionGroups {\n          content\n          users(first: 0) { totalCount }\n          viewerHasReacted\n        }\n      }\n    }\n  }\n";
/** Get the discussion category ID by name */
export declare const GET_CATEGORY_ID = "\n  query GetCategoryId($owner: String!, $name: String!, $slug: String!) {\n    repository(owner: $owner, name: $name) {\n      id\n      discussionCategory(slug: $slug) {\n        id\n      }\n      discussionCategories(first: 25) {\n        nodes {\n          id\n          name\n          slug\n        }\n      }\n    }\n  }\n";
/** Create a new discussion */
export declare const CREATE_DISCUSSION = "\n  mutation CreateDiscussion($repositoryId: ID!, $categoryId: ID!, $title: String!, $body: String!) {\n    createDiscussion(input: { repositoryId: $repositoryId, categoryId: $categoryId, title: $title, body: $body }) {\n      discussion {\n        id\n        title\n        url\n      }\n    }\n  }\n";
/** Add a comment to a discussion */
export declare const ADD_COMMENT = "\n  mutation AddComment($discussionId: ID!, $body: String!) {\n    addDiscussionComment(input: { discussionId: $discussionId, body: $body }) {\n      comment {\n        id\n        body\n        createdAt\n        author {\n          login\n          avatarUrl\n        }\n      }\n    }\n  }\n";
/** Reply to a discussion comment */
export declare const ADD_REPLY = "\n  mutation AddReply($discussionId: ID!, $replyToId: ID!, $body: String!) {\n    addDiscussionComment(input: { discussionId: $discussionId, body: $body, replyToId: $replyToId }) {\n      comment {\n        id\n        body\n        createdAt\n        author {\n          login\n          avatarUrl\n        }\n      }\n    }\n  }\n";
/** Update a discussion comment body */
export declare const UPDATE_COMMENT = "\n  mutation UpdateComment($commentId: ID!, $body: String!) {\n    updateDiscussionComment(input: { commentId: $commentId, body: $body }) {\n      comment {\n        id\n        body\n      }\n    }\n  }\n";
/** Delete a discussion comment */
export declare const DELETE_COMMENT = "\n  mutation DeleteComment($commentId: ID!) {\n    deleteDiscussionComment(input: { id: $commentId }) {\n      comment {\n        id\n      }\n    }\n  }\n";
/** Add a reaction */
export declare const ADD_REACTION = "\n  mutation AddReaction($subjectId: ID!, $content: ReactionContent!) {\n    addReaction(input: { subjectId: $subjectId, content: $content }) {\n      reaction {\n        content\n      }\n    }\n  }\n";
/** Remove a reaction */
export declare const REMOVE_REACTION = "\n  mutation RemoveReaction($subjectId: ID!, $content: ReactionContent!) {\n    removeReaction(input: { subjectId: $subjectId, content: $content }) {\n      reaction {\n        content\n      }\n    }\n  }\n";
/** List all discussions in a category */
export declare const LIST_DISCUSSIONS = "\n  query ListDiscussions($owner: String!, $name: String!, $categoryId: ID!) {\n    repository(owner: $owner, name: $name) {\n      discussions(first: 50, categoryId: $categoryId) {\n        nodes {\n          id\n          title\n          body\n          url\n          createdAt\n          comments {\n            totalCount\n          }\n        }\n      }\n    }\n  }\n";
